// One short, self-contained text blob per product. Labels are bilingual so a
// Hebrew or an English question hits the same chunk (the embeddings model is multilingual).
// Cost is deliberately left out — mock/policies/07-agent-guardrails.md forbids exposing margins.
const HE_CATEGORY = {
  Smartphones: 'סמארטפונים', Laptops: 'מחשבים ניידים', Tablets: 'טאבלטים',
  Audio: 'אודיו', Wearables: 'מתקנים לבישים', Accessories: 'אביזרים',
  Gaming: 'גיימינג', SmartHome: 'בית חכם', Cameras: 'מצלמות', Networking: 'תקשורת ורשתות'
};
const HE_STATUS = { Active: 'במלאי', Discontinued: 'הופסק שיווק', OutOfStock: 'אזל מהמלאי' };

return $input.all().map((item) => {
  const f = item.json.fields || item.json;
  const stock = Number(f.Stock || 0);
  const price = f.Price != null && f.Price !== '' ? `${Number(f.Price).toLocaleString('he-IL')} ₪ (כולל מע"מ) / ${f.Price} ILS` : 'מחיר לא זמין';

  const text = [
    `${f.Name || ''} — ${f.SKU || ''} (${f.ProductId || ''})`,
    `מותג / Brand: ${f.Brand || '-'}`,
    `קטגוריה / Category: ${HE_CATEGORY[f.Category] || f.Category || '-'} (${f.Category || '-'})`,
    `מחיר / Price: ${price}`,
    `מלאי / Stock: ${stock} יחידות`,
    `סטטוס / Status: ${HE_STATUS[f.Status] || f.Status || '-'}`,
    `אחריות / Warranty: ${f.Warranty || '-'}`,
    `תיאור / Description: ${f.Description || '-'}`
  ].join('\n');

  return { json: { sku: f.SKU || '', productId: f.ProductId || '', text } };
});
